import{_ as e,o as t,c as r,a5 as i}from"./chunks/framework.CnBNXlt7.js";const _=JSON.parse('{"title":"黑龙江","description":"","frontmatter":{},"headers":[],"relativePath":"trip/china/heilongjiang/index.md","filePath":"trip/china/heilongjiang/index.md","lastUpdated":1736840938000}'),s={name:"trip/china/heilongjiang/index.md"};function l(n,a,o,d,c,p){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="黑龙江" tabindex="-1">黑龙江 <a class="header-anchor" href="#黑龙江" aria-label="Permalink to &quot;黑龙江&quot;">​</a></h1><h2 id="哈尔滨" tabindex="-1">哈尔滨 <a class="header-anchor" href="#哈尔滨" aria-label="Permalink to &quot;哈尔滨&quot;">​</a></h2><details class="details custom-block"><summary>旅行参考 by 老乡pls 2023.04</summary><p>第一天晚上去中央大街，逛完直接能走到教堂。晚上教堂的灯光还不错，或者下午去教堂喂鸽子。<br> 上午去逛中华巴洛克，可以提前在抖音抢个团购票，竹筒奶茶只要9.9。<br> 风情街很多卖古玩的，建议只买10块以下的。顺着风情街走到松花江大桥那边，花两块坐船去太阳岛，太阳岛转弯可以选择坐索道回。或者去对面海洋馆，如果有对象建议和对象一起再去一个极地公园，极地公园有摩天轮。<br> 哈药六厂也可以去，不过他的人行道的路灯是坏的，不会绿，过马路容易被创死，我闯红灯过去了，差一点被创到。<br> 731遗址不怎么好看，不过可以去731博物馆，里边嘎嘎冷。<br> 哈师大夜市东西有点贵，还很小。哈师大附中也有一个夜市，也可以去逛逛，这俩很近。<br> 理工旁边的铁锅炖嘎嘎难吃。那个西西弗书店里边的奶茶嘎嘎贵。当然现在冰雪大世界关门了。</p></details><details class="details custom-block"><summary>哈尔滨零下二十四度穿衣攻略 by xw 2025.01.05</summary><p>上身: 300g 90鹅绒 半身羽绒服+p200抓绒+厚棉衬衣+厚保暖内衣 共4个<br> 下身: 抓绒冲锋裤+p100抓绒裤+保暖内衣配套的厚保暖裤+普通棉秋裤 共4个<br> 鞋: 巨厚的高帮雪地靴<br> 实测总结: 完全顶得住。<br> ps:</p><ol><li>脚免不了出汗，走到晚上会感觉很凉很难顶，此时使用发热鞋垫暖宝宝后效果拔群。</li><li>空气寒冷都顶得住，最怕刮大风，冰雪大世界全是冰雕建筑物，没啥风并不冷最冷的其实是松花江大桥，无建筑物有大风很难顶，此时下身应该使用厚棉裤代替普通棉裤。</li></ol></details>',4)])])}const b=e(s,[["render",l]]);export{_ as __pageData,b as default};
